import type { Datasets, Series } from './types';

// Types counted as health facilities. Bus stops are reported separately, never inside the health total.
export const HEALTH_TYPES = ['pharmacy', 'hospital', 'clinic', 'doctors'] as const;

export type YearValue = Series['series'][number];

// Compound annual rate in percent: (last / first) ^ (1 / years) - 1.
export function cagr(first: number, last: number, years: number): number {
  if (first <= 0) throw new Error('cagr: first value must be positive');
  if (years <= 0) throw new Error('cagr: years must be positive');
  if (last < 0) throw new Error('cagr: last value must not be negative');
  return (Math.pow(last / first, 1 / years) - 1) * 100;
}

// The change between the first and the last point of a series, with the years it spans.
export function span(series: YearValue[]): { first: YearValue; last: YearValue; years: number } | null {
  const first = series[0];
  const last = series[series.length - 1];
  if (!first || !last || last.year <= first.year) return null;
  return { first, last, years: last.year - first.year };
}

// 'down' when every year-on-year step is a fall, 'up' when every step is a rise, otherwise 'mixed'.
export function direction(series: YearValue[]): 'down' | 'up' | 'mixed' {
  if (series.length < 2) return 'mixed';
  let down = true;
  let up = true;
  for (let i = 1; i < series.length; i++) {
    const step = series[i]!.value - series[i - 1]!.value;
    if (step >= 0) down = false;
    if (step <= 0) up = false;
  }
  return down ? 'down' : up ? 'up' : 'mixed';
}

export type FacilitySplit = {
  health: { type: string; count: number; share: number }[];
  healthTotal: number;
  busStops: number;
  total: number;
};

// Health facilities by type in a fixed order, their share of the health total, and the bus stops apart.
export function splitFacilities(counts: Record<string, number>): FacilitySplit {
  const healthTotal = HEALTH_TYPES.reduce((sum, type) => sum + (counts[type] ?? 0), 0);
  const health = HEALTH_TYPES.map((type) => {
    const count = counts[type] ?? 0;
    return { type, count, share: healthTotal === 0 ? 0 : (count / healthTotal) * 100 };
  });
  const busStops = counts.bus_stop ?? 0;
  const other = Object.entries(counts)
    .filter(([type]) => type !== 'bus_stop' && !(HEALTH_TYPES as readonly string[]).includes(type))
    .reduce((sum, [, n]) => sum + n, 0);
  return { health, healthTotal, busStops, total: healthTotal + busStops + other };
}

// The newest generated_at among the dataset metas, as an ISO string.
export function newestStamp(stamps: string[]): string | null {
  const valid = stamps.filter((s) => !Number.isNaN(Date.parse(s)));
  if (valid.length === 0) return null;
  return valid.reduce((a, b) => (Date.parse(b) > Date.parse(a) ? b : a));
}

// "Last updated" for the page header: the newest build time among the three datasets.
export function updatedAt(datasets: Datasets): string | null {
  return newestStamp([
    datasets.population.meta.generated_at,
    datasets.physicians.meta.generated_at,
    datasets.facilities.meta.generated_at,
  ]);
}
